"""Independent decoding of the exact grayscale PNG generated by pbx_mobile.

The decoder is a separately pinned private QA dependency, never a PBX runtime
dependency. Callers verify and import it from their protected fixture directory.
"""
import json
import struct
import zlib


def decode_png(png, decoder):
    if not isinstance(png, bytes) or not 8 <= len(png) <= 2_000_000 or png[:8] != b'\x89PNG\r\n\x1a\n':
        raise ValueError('Bounded generated PNG required.')
    offset=8;chunks=[];dimensions=None;ended=False
    while offset<len(png):
        if len(png)-offset<12:raise ValueError('Truncated generated PNG.')
        size=struct.unpack('>I',png[offset:offset+4])[0];kind=png[offset+4:offset+8];offset+=8
        if size>1_000_000 or len(png)-offset<size+4:raise ValueError('Invalid PNG chunk bound.')
        data=png[offset:offset+size];crc=struct.unpack('>I',png[offset+size:offset+size+4])[0];offset+=size+4
        if zlib.crc32(kind+data)&0xffffffff!=crc:raise ValueError('Generated PNG checksum failed.')
        if kind==b'IHDR':
            if dimensions is not None or chunks or size!=13:raise ValueError('Invalid generated PNG header.')
            width,height,depth,color,compression,filtering,interlace=struct.unpack('>IIBBBBB',data)
            if not 1<=width<=2048 or not 1<=height<=2048 or (depth,color,compression,filtering,interlace)!=(8,0,0,0,0):
                raise ValueError('Exact generated grayscale PNG required.')
            dimensions=(height,width)
        elif kind==b'IDAT':
            if dimensions is None:raise ValueError('PNG data precedes its header.')
            chunks.append(data)
        elif kind==b'IEND':
            if size or offset!=len(png):raise ValueError('Invalid generated PNG ending.')
            ended=True;break
        else:raise ValueError('Unexpected generated PNG chunk.')
    if not ended or not dimensions or not chunks:raise ValueError('Incomplete generated PNG.')
    height,width=dimensions;expected=height*(width+1);stream=zlib.decompressobj();rows=stream.decompress(b''.join(chunks),expected+1)
    if len(rows)!=expected or not stream.eof or stream.unconsumed_tail or stream.unused_data:
        raise ValueError('Invalid generated PNG image bound.')
    raw=bytearray()
    for row in range(height):
        start=row*(width+1)
        if rows[start]!=0:raise ValueError('Unexpected generated PNG filter.')
        raw.extend(rows[start+1:start+width+1])
    barcode=decoder.read_barcode(memoryview(raw).cast('B',(height,width)),formats=decoder.BarcodeFormat.QRCode)
    if barcode is None or not barcode.valid:raise ValueError('The generated QR cannot be decoded.')
    payload=bytes(barcode.bytes)
    if len(payload)>4096:raise ValueError('Bounded phone setup payload required.')
    record=json.loads(payload)
    if not isinstance(record,dict) or set(record)!={'type','version','server','code','extension'}:
        raise ValueError('Exact password-free phone setup payload required.')
    if record['type']!='openwebpbx' or type(record['version'])is not int or record['version']!=1:
        raise ValueError('Unsupported phone setup payload.')
    return record
